# Stage S15e (11/05), generated by make_s15v3.py: EPR's own sweeps with a refinement gap
# Rule (as S14, S10c, S16): above the peak, quarter points of [best sustained rate, next tested rate], ascending until
# the first failing run; below a saturated peak, descending until the first sustained unsaturated run; a sweep that
# sustained its highest tested rate is extended by 10% steps until a run fails; rounds repeat while the peak moves.
XNAME=s15e
# 11/05: other users may load 116 this afternoon; from this stage on a run waits for a quiet host without the 2-hour
# cap of queue_1104.sh (which then runs anyway), so a busy host delays the runs but never contaminates them
quiet_or_wait() { local l=$1 n=0 l1
  while :; do
    read -r l1 _ < /proc/loadavg
    awk -v a=$l1 'BEGIN{exit !(a < 10)}' && break
    [ $((n % 6)) = 0 ] && qlog "PAUSE before $l: load $l1 (waiting, no time limit)"
    n=$((n+1)); sleep 300
  done
  echo "LOAD $l $(cut -d' ' -f1-3 /proc/loadavg) waited=$((n*5))min" >> $out; }
saturated() { local g; g=$(echo "$1" | grep -oE "whole_goodput=[0-9]+" | head -1 | cut -d= -f2); [ -n "$g" ] && [ $((g * 100)) -lt $(($2 * 95)) ]; }
xbody() {
  local R=$D/scripts/srv_run_evm6w.sh
  local RXO2="rxo2 epr 1 1 oldqueue REEXEC=1 REEXEC_BIN=$D/bin/d16reexec_v2 FX_EPR_PROG=1 REEXEC_ALL=1"
  local EPRZW="eprzw eprw 3 1 oldqueue FX_EPR_PROG=1 EPR_RO=1"
  local mode sc wl br bg nx up down x s img vc evm q ds gen r res extra it list
  # "<mode> <scheme> <workload> <best rate> <best goodput> <next tested rate or 0> <up points> <down points>"
  cat > $D/logs/s15e_groups.txt <<'TAB'
rk eprzw dex64 4200 4052 4550 4287,4375,4462 -
rk eprzw sb0.6 16000 15094 0 - -
rk eprzw usdt 6500 6408 7000 6625,6750,6875 -
rk eprzw z0 28000 19121 30000 28500,29000,29500 27500,27000,26500
rk eprzw z0.6 16000 13517 0 - -
rk eprzw z0.9 4500 4269 5000 4625,4750,4875 -
rk eprzw z1.2 1500 1497 1750 1562,1625,1687 -
pk eprzw dex64 4200 4108 4550 4287,4375,4462 -
pk eprzw usdt 6500 6405 7000 6625,6750,6875 -
TAB
  cat > $D/logs/s15e_next.py <<'PY'
import re, sys
best_only = sys.argv[1] == "--best"  # print the best sustained rate instead of the next rates
if best_only:
    del sys.argv[1]
mode, sc, wl, br, bg, nx, up = sys.argv[1].split()
br, bg, nx = int(br), float(bg), int(nx)
U = [int(x) for x in up.split(",") if x != "-"]
pts = {}
for f in sys.argv[2:]:
    try:
        lines = open(f, errors="replace")
    except OSError:
        continue
    cur = None
    for line in lines:
        if line.startswith("== "):
            m = re.match(r"== (rk|pk)_(\S+?)_([a-z0-9]+)_r(\d+) exit=", line)
            cur = int(m[4]) if m and (m[1], m[3], m[2]) == (mode, sc, wl) else None
            if cur is not None:
                pts[cur] = [None, None, None]
            continue
        if cur is not None:
            g = re.search(r"whole_goodput=([0-9.]+) lat_ms_p50=([0-9.]+)", line)
            if g:
                pts[cur][0], pts[cur][1] = float(g[1]), float(g[2])
            c = re.search(r"GOODPUT .*processed=(\d+)/\d+ success=(\d+)", line)
            if c and int(c[1]) > 0:
                pts[cur][2] = int(c[2]) / int(c[1])
ok = lambda p: p[0] is not None and p[1] is not None and p[1] <= 2000 and (mode == "pk" or (p[2] or 0) >= 0.95)
sus = {r: p[0] for r, p in pts.items() if ok(p)}
sus.setdefault(br, bg)
tested = set(pts) | {br} | ({nx} if nx else set())
best = max(sus, key=sus.get)
if best_only:
    print(best)
    sys.exit(0)
cand = set()
above = sorted(r for r in tested if r > best)
if best == br and U:  # peak unmoved: the rest of the original interval, unless a run there already failed
    tu = [r for r in U if r in pts]
    if all(ok(pts[r]) for r in tu):
        top = max(tu) if tu else br
        cand |= {r for r in U if r not in tested and r > top}
elif above and above[0] / best > 1.07:  # peak moved (or no original interval): its own quarter points
    cand |= {r for r in (best + (above[0] - best) * k // 4 for k in (1, 2, 3)) if r not in tested and r > best}
if not above:  # the sweep sustained its highest tested rate: one 10% step further
    cand.add(int(best * 1.1))
print(" ".join(map(str, sorted(cand))))
PY
  while read -r mode sc wl br bg nx up down; do
    case $sc in htf2) x="$HTF2";; rxo2) x="$RXO2";; fs) x="$FS";; fpp) x="$FPP";; fifo) x="$FIFO";; depg) x="$DEPG";;
      eprzw) x="$EPRZW";; *) continue;; esac
    set -- $x; s=$1 img=$2 vc=$3 evm=$4 q=$5; shift 5
    read -r ds gen <<< "$(dsof $wl)"
    extra=""; [ $mode = rk ] && extra="FX_RETRY=50"
    case $wl in dex*) extra="$extra OUTSTANDING=30000";; esac
    for r in ${down//,/ }; do
      [ "$r" = - ] && continue
      res=$(run ${mode}_${wl}_${s}_r$r $img $vc $evm $q $ds $gen FX_RATE=$r "$@" $extra < /dev/null)
      if sustained "$res" $mode && ! saturated "$res" $r; then echo "REFINE_OK ${mode}_${wl}_${s} at r=$r (below)" | tee -a $out; break; fi
      echo "REFINE_NEXT ${mode}_${wl}_${s} at r=$r (below)" | tee -a $out
    done
    for it in 1 2 3 4; do
      list=$(python3 $D/logs/s15e_next.py "$mode $sc $wl $br $bg $nx $up" $D/logs/q1103_s15e.txt)
      [ -n "$list" ] || break
      echo "REFINE_ROUND $it ${mode}_${wl}_${s}: $list" | tee -a $out
      for r in $list; do
        res=$(run ${mode}_${wl}_${s}_r$r $img $vc $evm $q $ds $gen FX_RATE=$r "$@" $extra < /dev/null)
        if ! sustained "$res" $mode; then echo "REFINE_STOP ${mode}_${wl}_${s} at r=$r" | tee -a $out; break; fi
        echo "REFINE_OK ${mode}_${wl}_${s} at r=$r" | tee -a $out
      done
    done
    # EPR's peaks of Fig. 8 are measured three times (Setup): a peak that moved gets two repeats (as S14/S14r)
    if [ $sc = eprzw ] && [ $mode = rk ] && echo " usdc usdt z0.8 z0.99 sb0.8 sb1.0 sb1.2 dex1 dex16 dex64 " | grep -q " $wl "; then
      r=$(python3 $D/logs/s15e_next.py --best "$mode $sc $wl $br $bg $nx $up" $D/logs/q1103_s15e.txt)
      if [ -n "$r" ] && [ "$r" != "$br" ]; then
        echo "REPEAT ${mode}_${wl}_${s} new peak at r=$r" | tee -a $out
        for it in 1 2; do run ${mode}_${wl}_${s}rp${it}_r$r $img $vc $evm $q $ds $gen FX_RATE=$r "$@" $extra < /dev/null > /dev/null; done
      fi
    fi
    save
  done < $D/logs/s15e_groups.txt
  echo "S15E refinements done" | tee -a $out
}
